package ru.avrescue.app;

import android.app.*;import android.os.*;import android.content.*;import android.text.InputType;import android.widget.*;import org.json.JSONObject;

public class VerificationActivity extends Activity {
 protected void onStart(){super.onStart();getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_SECURE);}
 String accountType,id,verificationToken,channel="phone";TextView title,target,status;EditText code;Button send,confirm;
 public void onCreate(Bundle b){super.onCreate(b);accountType=getIntent().getStringExtra("account_type");id=getIntent().getStringExtra("id");verificationToken=getIntent().getStringExtra("verification_token");if(accountType==null||id==null||verificationToken==null){finish();return;}render();loadStatus(true);}
 void render(){LinearLayout page=Ui.column(this);page.addView(Ui.brand(this));LinearLayout card=Ui.card(this);title=Ui.text(this,"Подтверждение телефона",24,true);target=Ui.muted(this,"",15);status=Ui.muted(this,"",14);code=Ui.input(this,"6 цифр из SMS");code.setInputType(InputType.TYPE_CLASS_NUMBER);send=Ui.darkButton(this,"Получить новый код");confirm=Ui.button(this,"Подтвердить телефон");card.addView(title);card.addView(Ui.muted(this,"Сначала подтвердите телефон, затем электронную почту.",15));card.addView(target);card.addView(code);card.addView(confirm);card.addView(send);card.addView(status);page.addView(card);setContentView(page);send.setOnClickListener(v->sendCode());confirm.setOnClickListener(v->confirmCode());}
 JSONObject base(String action)throws Exception{return new JSONObject().put("action",action).put("account_type",accountType).put("id",id).put("verification_token",verificationToken).put("channel",channel);}
 void loadStatus(boolean sendFirst){status.setText("Проверяем статус…");new Thread(()->{try{JSONObject r=ApiClient.post("/api/mobile_verification.php",base("status"));runOnUiThread(()->{if(!r.optBoolean("ok")){status.setText(r.optString("error","Ошибка подтверждения"));return;}if(r.optBoolean("complete")){completed();return;}channel=r.optBoolean("phone_verified")?"email":"phone";updateStep(r);if(sendFirst)sendCode();});}catch(Exception e){runOnUiThread(()->status.setText("Нет связи с AV Rescue"));}}).start();}
 void updateStep(JSONObject r){boolean email=channel.equals("email");title.setText(email?"Подтверждение почты":"Подтверждение телефона");target.setText(email?r.optString("email_masked",""):r.optString("phone_masked",""));code.setHint(email?"6 цифр из письма":"6 цифр из SMS");confirm.setText(email?"Подтвердить почту":"Подтвердить телефон");}
 void sendCode(){status.setText(channel.equals("email")?"Отправляем письмо…":"Отправляем SMS…");new Thread(()->{try{JSONObject r=ApiClient.post("/api/mobile_verification.php",base("send"));runOnUiThread(()->status.setText(r.optBoolean("ok")?"Код отправлен. Он может прийти в течение минуты.":r.optString("error","Не удалось отправить код")));}catch(Exception e){runOnUiThread(()->status.setText("Нет связи с AV Rescue"));}}).start();}
 void confirmCode(){String value=code.getText().toString().trim();if(value.length()!=6){status.setText("Введите код из 6 цифр");return;}status.setText("Проверяем код…");new Thread(()->{try{JSONObject q=base("confirm").put("code",value);JSONObject r=ApiClient.post("/api/mobile_verification.php",q);runOnUiThread(()->{if(!r.optBoolean("ok")){status.setText(r.optString("error","Неверный код"));return;}code.setText("");if(r.optBoolean("complete"))completed();else{channel="email";loadStatus(true);}});}catch(Exception e){runOnUiThread(()->status.setText("Нет связи с AV Rescue"));}}).start();}
 void completed(){title.setText("Контакты подтверждены");target.setText("Теперь можно войти в приложение. Для водителей и B2B доступ откроется после модерации администратора.");code.setVisibility(android.view.View.GONE);send.setVisibility(android.view.View.GONE);confirm.setText("Перейти ко входу");confirm.setOnClickListener(v->{startActivity(new Intent(this,LoginActivity.class));finishAffinity();});status.setText("");}
}
